import{_ as o,o as r,c as p,a5 as n}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"904-批量文件查重","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-14T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["图片批处理"],"标签":["Python图片处理","图片去重软件","图片查重工具","图片相似度检测","图片管理","感知哈希算法","批量删除重复图片","相似图片查找","重复图片检测"]},"headers":[],"relativePath":"md/图片批处理/904-批量文件查重.md","filePath":"md/图片批处理/904-批量文件查重.md"}'),s={name:"md/图片批处理/904-批量文件查重.md"};function a(d,t,l,e,i,g){return r(),p("div",null,[...t[0]||(t[0]=[n('<p>图片查重/去重工具是一款专业的图片管理软件，快速识别和处理重复或相似的图片文件。该工具基于<strong>感知哈希算法</strong>实现图片相似度检测，支持<strong>精确重复检测</strong>和<strong>相似图片查找</strong>两种模式</p><p>该软件的核心功能包括：通过计算图片的平均哈希值来识别完全相同的图片文件；通过比较哈希差值来发现视觉上相似的图片；支持递归扫描子目录；提供安全的删除确认机制；实时显示处理进度和操作日志。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260220163933177157677332181.png" alt=""></p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><p>精确重复检测：通过计算图片的平均哈希值，快速识别完全相同的图片文件。无论文件名如何变化，只要图片内容相同，都能被准确识别出来。</p><p>相似图片查找：采用感知哈希算法比较图片的视觉特征，可检测出经过压缩、裁剪、调色等处理后的相似图片。用户可自定义相似度阈值（1-20），阈值越小匹配越严格。</p><p><strong>双界面支持：</strong></p><p>同时提供图形用户界面（GUI）和命令行界面（CLI）。图形界面直观易用，适合普通用户；</p><p>命令行界面灵活高效，适合批量处理和自动化脚本。</p><p><strong>递归搜索</strong>：支持递归扫描子目录，一键查找整个文件夹树中的重复图片，无需手动逐个目录检查。</p><p><strong>安全删除机制</strong>：删除操作前会显示详细的文件列表供用户确认，图形界面中标记保留和删除的文件，命令行界面需要用户输入确认，防止误删重要文件。</p><p><strong>实时进度反馈</strong>：处理过程中实时显示进度条和当前处理的文件名，让用户了解任务执行状态。</p><p><strong>多格式支持</strong>：支持常见的图片格式，包括JPG、JPEG、PNG、BMP、GIF、TIFF、WEBP等。</p><h3 id="详细使用说明" tabindex="-1">详细使用说明 <a class="header-anchor" href="#详细使用说明" aria-label="Permalink to &quot;详细使用说明&quot;">​</a></h3><p><strong>图形界面使用说明</strong></p><p>图形界面采用标签页设计，主要包含图片查重标签页和关于标签页。</p><p><strong>目录选择区域</strong>：通过输入框直接输入目录路径，或点击”浏览…”按钮打开文件夹选择对话框。</p><p><strong>选项配置区域</strong>：</p><ul><li>查找模式：选择”精确重复”检测完全相同的图片，或”相似图片”检测视觉相似的图片</li><li>相似度阈值：拖动滑块设置相似度判定标准（仅在相似图片模式下生效），数值越小要求越严格</li><li>递归搜索子目录：勾选后将扫描所选目录下的所有子文件夹</li></ul><p><strong>控制按钮</strong>：</p><ul><li>开始查找：启动扫描任务，扫描期间按钮会变为禁用状态</li><li>删除选中：删除标记为”[删除]”或”[相似]”的文件，扫描完成后自动启用</li><li>清除结果：清空当前结果列表，重置界面状态</li></ul><p><strong>结果列表区域</strong>：以表格形式展示扫描结果，包含状态、文件路径、文件大小、所属分组四列。绿色标记的”[保留]”或”[原始]”文件将被保留，红色标记的”[删除]”或”[相似]”文件为待删除项。</p><p><strong>日志区域</strong>：底部滚动文本框实时显示操作日志，包括扫描进度、处理结果、错误信息等。</p><p><strong>命令行界面使用说明</strong></p><p>命令行界面提供完整的参数控制，适合批量处理和脚本集成。</p><p><strong>基本参数</strong>：</p><table tabindex="0"><thead><tr><th>参数</th><th>简写</th><th>说明</th></tr></thead><tbody><tr><td>—path</td><td>-p</td><td>图片目录路径（必填）</td></tr><tr><td>—recursive</td><td>-r</td><td>递归搜索子目录</td></tr><tr><td>—delete</td><td>-d</td><td>删除重复文件</td></tr><tr><td>—no-confirm</td><td>-N</td><td>删除时不确认（需与-d一起使用）</td></tr><tr><td>—similar</td><td>-s</td><td>查找相似图片模式</td></tr><tr><td>—threshold</td><td>-t</td><td>相似度阈值（1-20，默认5）</td></tr><tr><td>—threshold</td><td>-t</td><td>相似度阈值（1-20，默认5）</td></tr></tbody></table><p><strong>使用示例</strong>：</p><p>仅显示重复图片（不删除）：<code>python源代码.py -p D:\\Photos</code><br> 1.</p><p>递归查找所有子目录：<code>python源代码.py -r -p D:\\Photos</code><br> 1.</p><p>查找并删除重复文件（需确认）：<code>python源代码.py -r -d -p D:\\Photos</code><br> 1.</p><p>直接删除不确认（谨慎使用）：<code>python源代码.py -r -d -N -p D:\\Photos</code><br> 1.</p><p>查找相似图片（阈值10）：<code>python源代码.py -r -s -t 10 -p D:\\Photos</code><br> 1.</p><h3 id="使用场景示例" tabindex="-1">使用场景示例 <a class="header-anchor" href="#使用场景示例" aria-label="Permalink to &quot;使用场景示例&quot;">​</a></h3><p><strong>场景一：整理手机备份照片</strong></p><p>用户从手机导出了多年的照片备份，文件夹结构复杂，存在大量重复照片。使用本工具可以快速清理：</p><ol><li>运行图形界面，选择照片备份根目录</li><li>勾选”递归搜索子目录”</li><li>选择”精确重复”模式</li><li>点击”开始查找”，等待扫描完成</li><li>检查结果列表，确认无误后点击”删除选中”</li><li>工具会自动保留每组重复文件中的一个，删除其余副本</li></ol><p><strong>场景二：筛选相似素材图片</strong></p><p>设计师需要从大量素材中筛选出相似的图片进行整理。这些图片可能经过压缩、裁剪或调色处理：</p><ol><li>运行图形界面，选择素材文件夹</li><li>勾选”递归搜索子目录”</li><li>选择”相似图片”模式</li><li>根据需要调整相似度阈值（建议从5开始尝试）</li><li>点击”开始查找”进行扫描</li><li>查看结果，根据实际相似度调整阈值重新扫描</li><li>确认后删除不需要的版本</li></ol><p><strong>场景三：服务器批量清理重复图片</strong></p><p>网站服务器积累了大量用户上传的图片，需要定期清理重复文件以节省存储空间。使用命令行界面可以方便地集成到定时任务中：</p><ol><li><code># 查看重复图片列表</code></li><li><code>python源代码.py -r -v -p /var/www/uploads/images</code></li><li><code># 确认后执行删除（需要确认）</code></li><li><code>python源代码.py -r -d -p /var/www/uploads/images</code></li><li><code># 或集成到脚本中自动执行（不确认）</code></li><li><code>python源代码.py -r -d -N -p /var/www/uploads/images</code></li></ol><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p>数据备份：在执行删除操作前，强烈建议对重要图片进行备份。虽然工具提供了确认机制，但数据安全始终是首要考虑。</p><p>删除不可恢复：文件删除操作是永久性的，无法通过回收站恢复。请务必仔细核对删除列表后再确认操作。</p><p><strong>相似度阈值调整</strong>：相似图片模式下，阈值设置对结果影响较大。建议先用较小的阈值测试，再根据实际需求调整。</p><p><strong>大文件处理</strong>：处理大量图片时可能需要较长时间，请耐心等待。图形界面会显示实时进度，命令行可使用-v参数查看详细信息。</p><p><strong>文件权限</strong>：确保程序对目标目录有读取权限，对需要删除的文件有写入权限。</p><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><p><strong>Q: 为什么有些明显相同的图片没有被识别为重复？</strong></p><p>A: 如果图片经过了重新编码、压缩或格式转换，其哈希值可能会发生变化。建议使用”相似图片”模式，并适当调高阈值。</p><p><strong>Q: 删除文件时提示”删除失败”怎么办？</strong></p><p>A: 可能原因包括：文件被其他程序占用、文件权限不足、文件路径包含特殊字符等。请关闭可能占用文件的程序，或以管理员权限运行工具。</p><p><strong>Q: 相似度阈值应该设置为多少？</strong></p><p>A: 默认值5适用于大多数场景。阈值越小匹配越严格（只检测非常相似的图片），阈值越大匹配越宽松（可能检测出不太相似的图片）。建议从默认值开始，根据实际结果调整。</p><p><strong>Q: 支持哪些图片格式？</strong></p><p>A: 支持JPG、JPEG、PNG、BMP、GIF、TIFF、WEBP等常见格式。对于不支持的格式，程序会跳过并记录日志。</p><p><strong>Q: 删除时会保留哪个文件？</strong></p><p>A: 每组重复文件中，程序会保留文件名排序后的第一个文件，其余文件标记为待删除。可以在图形界面中查看具体标记。</p><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>解压后，看到如下文件，双击快捷方式使用即可（快捷方式上有个箭头），快捷方式可以放到任意位置。</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260221121136177164709692450.png" alt=""></p><p><strong>如下所示，文件夹及文件夹内所有内容都不要删除，如果突然无法使用了大概率是杀毒软件给误杀了，请重新解压使用即可</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260221121150177164711077123.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2591.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2591.html</a></p>',72)])])}const m=o(s,[["render",a]]);export{c as __pageData,m as default};
